node --input-type=module - <<'JS'
import fs from 'node:fs';
const lib=JSON.parse(fs.readFileSync('node_modules/@maxvue/max-components-ui/package.json','utf8'));
const expected={pinia:'^4.0.0','vue-router':'^5.2.0'};
let failed=false;
for(const [name,range] of Object.entries(expected)) {
 if(lib.peerDependencies[name]!==range) throw new Error('Contrato de peer mudou: reavaliar '+name);
 const installed=JSON.parse(fs.readFileSync('node_modules/'+name+'/package.json','utf8')).version;
 const actual=installed.split('.').map(Number);
 const minimum=range.slice(1).split('.').map(Number);
 const compatible=actual[0]===minimum[0]&&(actual[1]>minimum[1]||(actual[1]===minimum[1]&&actual[2]>=minimum[2]));
 console.log(name+': instalado '+installed+', exigido '+range+', '+(compatible?'compatível':'fora da faixa declarada'));
 if(!compatible) failed=true;
}
process.exitCode=failed?1:0;
JS
